:root {
  --color-bg: #f6f7fb;
  --color-surface: #ffffff;
  --color-border: #dde1ea;
  --color-text: #1f2430;
  --color-text-muted: #5b6270;
  --color-primary: #3452e1;
  --color-primary-contrast: #ffffff;
  --color-danger: #d1364a;
  --color-success: #1f8a4c;
  --color-seat-free: #e4e8f5;
  --color-seat-selected: #3452e1;
  --color-seat-occupied: #c7cbd6;
  --color-aisle: transparent;

  color-scheme: light;
  font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji';
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  background: var(--color-bg);
  color: var(--color-text);
}

h1,
h2,
h3 {
  font-weight: 600;
  line-height: 1.25;
}

button {
  font-family: inherit;
  cursor: pointer;
}

button:disabled {
  cursor: not-allowed;
}

a {
  color: var(--color-primary);
}

.card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: 0.75rem;
  padding: 1.25rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  border-radius: 0.5rem;
  border: 1px solid transparent;
  padding: 0.6rem 1.1rem;
  font-size: 0.95rem;
  font-weight: 600;
  transition: background 0.15s ease, border-color 0.15s ease, opacity 0.15s ease;
}

.btn-primary {
  background: var(--color-primary);
  color: var(--color-primary-contrast);
}

.btn-primary:disabled {
  opacity: 0.5;
}

.btn-primary:not(:disabled):hover {
  background: color-mix(in srgb, var(--color-primary) 85%, black);
}

.btn-secondary {
  background: var(--color-surface);
  border-color: var(--color-border);
  color: var(--color-text);
}

.btn-secondary:not(:disabled):hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.btn-danger {
  background: var(--color-surface);
  border-color: var(--color-danger);
  color: var(--color-danger);
}

.btn-danger:not(:disabled):hover {
  background: var(--color-danger);
  color: white;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;

  label {
    font-weight: 600;
    font-size: 0.9rem;
  }

  input,
  select {
    font-family: inherit;
    font-size: 0.95rem;
    padding: 0.55rem 0.7rem;
    border-radius: 0.5rem;
    border: 1px solid var(--color-border);
    background: var(--color-surface);
    color: var(--color-text);
  }

  input:focus,
  select:focus {
    outline: 2px solid var(--color-primary);
    outline-offset: 1px;
  }
}

.error-banner {
  background: color-mix(in srgb, var(--color-danger) 10%, white);
  border: 1px solid var(--color-danger);
  color: var(--color-danger);
  border-radius: 0.5rem;
  padding: 0.75rem 1rem;
}

.success-banner {
  background: color-mix(in srgb, var(--color-success) 10%, white);
  border: 1px solid var(--color-success);
  color: var(--color-success);
  border-radius: 0.5rem;
  padding: 0.75rem 1rem;
}

.muted {
  color: var(--color-text-muted);
}

